target.script:

var File = Java.type("java.io.File");
var FileInputStream = Java.type("java.io.FileInputStream");
var FileOutputStream = Java.type("java.io.FileOutputStream");
var BufferedInputStream = Java.type("java.io.BufferedInputStream");
var GZIPOutputStream = Java.type("java.util.zip.GZIPOutputStream");

var root = new File(project.getProperty("project.build.directory"), "app/data/lore");

var mapsDir = new File(root, "maps");
var gitignore = new File(mapsDir, ".gitignore");
if (gitignore.exists()) { gitignore.delete(); project.log("removed: " + gitignore); }
var githubDir = new File(mapsDir, ".github");
if (githubDir.exists()) {
  var wf = new File(githubDir, "workflows/sync-upstream.yml");
  if (wf.exists()) { wf.delete(); project.log("removed: " + wf); }
  new File(githubDir, "workflows").delete();
  githubDir.delete();
  project.log("removed: " + githubDir);
}

function gzipDir(dir) {
  var files = dir.listFiles();
  if (files == null) return;
  for (var i = 0; i < files.length; i++) {
    var f = files[i];
    if (f.isDirectory()) {
      gzipDir(f);
    } else if (f.isFile() && f.getName().endsWith(".xml")) {
      var outFile = new File(f.getParentFile(), f.getName() + ".gz");
      var is = new BufferedInputStream(new FileInputStream(f));
      var os = new GZIPOutputStream(new FileOutputStream(outFile));
      var buf = java.lang.reflect.Array.newInstance(java.lang.Byte.TYPE, 65536);
      var n;
      while ((n = is.read(buf)) != -1) {
        os.write(buf, 0, n);
      }
      is.close();
      os.close();
      f.delete();
      project.log("gzipped: " + outFile);
    }
  }
}

function convertMapImages(mapsSubdir) {
  if (!mapsSubdir.exists()) return;
  var mapFiles = mapsSubdir.listFiles();
  if (mapFiles == null) return;

  var ImageIO = Java.type("javax.imageio.ImageIO");
  var ImageWriteParam = Java.type("javax.imageio.ImageWriteParam");
  var IIOImage = Java.type("javax.imageio.IIOImage");
  var FileImageOutputStream = Java.type("javax.imageio.stream.FileImageOutputStream");
  var BufferedImage = Java.type("java.awt.image.BufferedImage");
  var Color = Java.type("java.awt.Color");

  var writers = ImageIO.getImageWritersByFormatName("jpg");
  if (!writers.hasNext()) {
    project.log("No JPEG writer found!");
    return;
  }
  var writer = writers.next();
  var writeParam = writer.getDefaultWriteParam();
  writeParam.setCompressionMode(ImageWriteParam.MODE_EXPLICIT);
  writeParam.setCompressionQuality(0.85);

  var count = 0;
  for (var i = 0; i < mapFiles.length; i++) {
    var f = mapFiles[i];
    if (f.isFile() && f.getName().endsWith(".png")) {
      var name = f.getName();
      var outName = name.substring(0, name.length - 4) + ".jpg";
      var outFile = new File(mapsSubdir, outName);
      try {
        var srcImg = ImageIO.read(f);
        if (srcImg != null) {
          var rgbImg = new BufferedImage(srcImg.getWidth(), srcImg.getHeight(), BufferedImage.TYPE_INT_RGB);
          var g = rgbImg.createGraphics();
          g.drawImage(srcImg, 0, 0, Color.WHITE, null);
          g.dispose();

          var fios = new FileImageOutputStream(outFile);
          writer.setOutput(fios);
          writer.write(null, new IIOImage(rgbImg, null, null), writeParam);
          fios.close();
          f.delete();
          count++;
        }
      } catch (err) {
        project.log("Failed to convert " + f + ": " + err);
      }
    }
  }
  writer.dispose();
  project.log("Converted " + count + " map images to JPEG (.jpg).");
}

if (root.exists()) {
  gzipDir(root);
  convertMapImages(new File(mapsDir, "maps"));
}
